function countExcellentPairs(nums, k) {
  const byBits = new Array(31).fill(0);

  for (const num of new Set(nums)) {
    let bits = 0;
    let value = num;
    while (value > 0) {
      value &= value - 1;
      bits++;
    }
    byBits[bits]++;
  }

  let pairs = 0;
  for (let a = 1; a <= 30; a++) {
    for (let b = 1; b <= 30; b++) {
      if (a + b >= k) {
        pairs += byBits[a] * byBits[b];
      }
    }
  }
  return pairs;
}

